using Microsoft.EntityFrameworkCore;using Namaa.Application.Abstractions.Persistence;using Namaa.Domain.Entities;namespace Namaa.Infrastructure.Persistence.Repositories;public sealed class PaymentRepository(NamaaDbContext db):IPaymentRepository{public Task<bool>ExistsByPaymentNumberAsync(string value,CancellationToken cancellationToken=default)=>db.Payments.AsNoTracking().AnyAsync(e=>e.PaymentNumber==value,cancellationToken);public Task<Payment?>FindByIdAsync(long id,CancellationToken cancellationToken=default)=>db.Payments.AsNoTracking().SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public Task<Payment?>FindForUpdateAsync(long id,CancellationToken cancellationToken=default)=>db.Payments.SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public async Task<IReadOnlyList<Payment>>GetAllAsync(CancellationToken cancellationToken=default)=>await db.Payments.AsNoTracking().OrderBy(e=>e.Id).ToListAsync(cancellationToken);public async Task AddAsync(Payment entity,CancellationToken cancellationToken=default)=>await db.Payments.AddAsync(entity,cancellationToken);}
